	}

	dataDir := config.DataDir()
	if err := config.SetMachineEnabled(dataDir, false); err != nil {
		return fmt.Errorf("disabling machine memory: %w", err)
	}
	fmt.Fprintln(cmd.OutOrStdout(), "Disabled repository memory globally")
	return nil
}
